const DB='OsRaDB', VER=1, THUMB_VERSION=3, THUMB_MAX_BYTES=128*1024;
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const DEFAULT={settings:{startDate:'',engagementDate:'',birthdayRania:'',osamaPhone:'',raniaPhone:'',whatsappUrl:'',libraryName:'',soundEnabled:false,dailyAlbumIds:null,albumOrderMode:'manual'},memories:[],events:[],dreams:[],verses:[],prayers:[],messages:[],excludedPhotos:[]};
let db,state=structuredClone(DEFAULT),libraryHandle=null,backupFileHandle=null,backupMeta={lastSavedAt:0,lastAutoFileAt:0},photos=new Map(),section='home',busy=false,installEvent=null,soundOn=false,audioCtx=null,lb={ids:[],i:0,url:null,timer:null,touchX:null,touchY:null},currentMemoryId=null,selectedPhotos=new Set(),selectedMemories=new Set(),calendarDate=today(),calendarCursor=null,safetyTimer=null;
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=p=>p+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8);
const mediaTypeOf=p=>p?.mediaType==='video'?'video':'image';
const allMedia=()=>[...photos.values()].filter(p=>!p.excluded);
const allPhotos=()=>allMedia().filter(p=>mediaTypeOf(p)==='image');
const allVideos=()=>allMedia().filter(p=>mediaTypeOf(p)==='video');
function toast(m){const t=$('#toast');if(!t)return;t.textContent=m;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),2800)}
function dbOpen(){return new Promise((ok,no)=>{const r=indexedDB.open(DB,VER);r.onupgradeneeded=()=>{const d=r.result;if(!d.objectStoreNames.contains('state'))d.createObjectStore('state',{keyPath:'key'});if(!d.objectStoreNames.contains('photos'))d.createObjectStore('photos',{keyPath:'id'});if(!d.objectStoreNames.contains('library'))d.createObjectStore('library',{keyPath:'key'})};r.onsuccess=()=>{db=r.result;ok()};r.onerror=()=>no(r.error)})}
const get=(s,k)=>new Promise((ok,no)=>{const r=db.transaction(s).objectStore(s).get(k);r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)});
const put=(s,v)=>new Promise((ok,no)=>{const r=db.transaction(s,'readwrite').objectStore(s).put(v);r.onsuccess=()=>ok();r.onerror=()=>no(r.error)});
const del=(s,k)=>new Promise((ok,no)=>{const r=db.transaction(s,'readwrite').objectStore(s).delete(k);r.onsuccess=()=>ok();r.onerror=()=>no(r.error)});
