async function load(){const s=await get('state','main');if(s){state={...structuredClone(DEFAULT),...s.value}}normalizeState();const l=await get('library','main');if(l?.handle){libraryHandle=l.handle;state.settings.libraryName=l.name||l.handle.name}const b=await get('library','backup');if(b?.handle){backupFileHandle=b.handle;backupMeta={lastSavedAt:+b.lastSavedAt||0,lastAutoFileAt:+b.lastAutoFileAt||0}}photos=new Map((await getAll('photos')).map(x=>[x.id,{...x,excluded:!!x.excluded}]));}
