function detailScore(m){const media=mediaFor(m).length;return (m.date?30:0)+(m.endDate&&m.endDate!==m.date?10:0)+(m.place?20:0)+(m.description?Math.min(25,5+Math.floor(String(m.description).length/60)*5):0)+(m.title?5:0)+Math.min(20,media*2)}
