function exclusionKey(relPath,size,lastModified,fingerprint=''){return `${fingerprint||''}|${relPath}|${size}|${lastModified}`}
function isExcluded(relPath,size,lastModified,fingerprint=''){return state.excludedPhotos.some(x=>(fingerprint&&x.fingerprint&&x.fingerprint===fingerprint)||(x.key===exclusionKey(relPath,size,lastModified,fingerprint))||(x.relPath===relPath&&x.size===size&&x.lastModified===lastModified))}
function removeFromAutoAlbum(pid,album){if(!album)return;const m=state.memories.find(x=>x.album===album&&x.autoAlbum!==false);if(m)m.photoIds=(m.photoIds||[]).filter(x=>x!==pid)}
