   let f;try{f=await e.getFile()}catch{continue}
   const imageByMime=/^image\//i.test(f.type||''),videoByMime=/^video\//i.test(f.type||'');
   if(!isMedia(name)&&!imageByMime&&!videoByMime)continue;count++;
   const mediaType=videoByMime||isVideo(name)?'video':'image',mimeType=f.type||'';let fp=await fingerprint(f),ck=await contentKey(f);
