function videoEl(){return $('#lbVideo')}
function setVideoSpeed(v){const x=videoEl();if(x){x.playbackRate=Number(v);$('#videoSpeedLabel').textContent=x.playbackRate+'×'}}
function setVideoVolume(v){const x=videoEl();if(x)x.volume=Number(v)}
function setVideoBrightness(v){const x=videoEl();if(x)x.style.filter=`brightness(${Number(v)/100})`;$('#videoBrightnessLabel').textContent=v+'%'}
function rotateVideo(){const x=videoEl();if(!x)return;const r=(Number(x.dataset.rotate||0)+90)%360;x.dataset.rotate=r;x.style.transform=`rotate(${r}deg) scale(${Number(x.dataset.zoom||100)/100})`}
function zoomVideo(delta){const x=videoEl();if(!x)return;const z=Math.min(160,Math.max(70,Number(x.dataset.zoom||100)+delta));x.dataset.zoom=z;x.style.transform=`rotate(${Number(x.dataset.rotate||0)}deg) scale(${z/100})`}
async function fullscreenVideo(){const x=videoEl();if(!x)return;try{if(document.fullscreenElement)await document.exitFullscreen();else await x.requestFullscreen?.()}catch{try{await x.webkitEnterFullscreen?.()}catch{}}}
async function pipVideo(){const x=videoEl();if(!x||!document.pictureInPictureEnabled||!x.requestPictureInPicture)return;try{if(document.pictureInPictureElement)await document.exitPictureInPicture();else await x.requestPictureInPicture()}catch{toast('الوضع العائم غير متاح لهذا الفيديو على هذا الجهاز.')}}
function closeLB(){stopSlideshow();const v=$('#lbVideo');if(v){v.pause();v.removeAttribute('src');v.load();}if(lb.url)URL.revokeObjectURL(lb.url);lb.url=null;romanticHeartTransition('close');if($('#lightbox')?.open)$('#lightbox').close()}
function modal(html){$('#modalBody').innerHTML=html;$('#modal').showModal()}function closeModal(){if($('#modal').open)$('#modal').close()}
function memoryForm(m){const start=m.date||'',end=m.endDate||m.date||'';modal(`<h2>تفاصيل الذكرى</h2>${field('mTitle','اسم الذكرى',m.title,'text')}<div class="field"><label>من تاريخ</label><input id="mDate" type="date" value="${esc(start)}"></div><div class="field"><label>إلى تاريخ</label><input id="mEndDate" type="date" value="${esc(end)}"><small class="meta">النهاية تبدأ تلقائيًا مثل البداية. غيّرها فقط إذا كانت الذكرى تمتد لأكثر من يوم.</small></div>${field('mPlace','المكان',m.place,'text')}<div class="field"><label>الوصف</label><textarea id="mDesc">${esc(m.description||'')}</textarea></div><div class="actions"><button class="btn primary" data-action="saveMemory" data-id="${m.id}">حفظ</button><button class="btn" data-action="closeModal">إلغاء</button></div>`);const sd=$('#mDate'),ed=$('#mEndDate');if(ed)ed.dataset.auto=(!!start&&end===start)||(!start&&!end)?'1':'0';sd?.addEventListener('change',()=>{if(ed&&(ed.dataset.auto==='1'||!ed.value)) {ed.value=sd.value;ed.dataset.auto='1';}});ed?.addEventListener('input',()=>{if(ed.value!==sd?.value)ed.dataset.auto='0';});}
function editMemory(i){const m=state.memories.find(x=>x.id===i);if(m)memoryForm(m)}
function addMemory(){const m={id:id('mem'),title:'',date:'',endDate:'',place:'',description:'',album:'',photoIds:[],userEdited:true};state.memories.unshift(m);memoryForm(m)}
function albumForm(){modal(`<h2>ألبوم جديد</h2>${field('albumTitle','اسم الألبوم','','text')}<p class="meta">يمكنك بعد إنشائه تحديد صور من أي ذكرى ونقلها إليه، بدون حذف الصور الأصلية.</p><div class="actions"><button class="btn primary" data-action="saveAlbum">إنشاء</button><button class="btn" data-action="closeModal">إلغاء</button></div>`)}
function newAlbum(){albumForm()}
function dreamForm(d){modal(`<h2>${d?'تعديل الحلم':'حلم جديد'}</h2>${field('dTitle','الحلم',d?.title||'','text')}${field('dDate','الموعد المستهدف',d?.targetDate||'','date')}${field('dProgress','نسبة الإنجاز',d?.progress??0,'number')}<div class="field"><label>التفاصيل</label><textarea id="dNote">${esc(d?.note||'')}</textarea></div><div class="actions"><button class="btn primary" data-action="saveDream" data-id="${d?.id||''}">حفظ</button><button class="btn" data-action="closeModal">إلغاء</button></div>`)}
